const std = @import("std");

pub fn main() !void {
    const word = "racecar";
    var is_palindrome = true;

    for (0..word.len / 2) |i| {
        if (word[i] != word[word.len - 1 - i]) {
            is_palindrome = false;
            break;
        }
    }

    if (is_palindrome) {
        std.debug.print("{} is a palindrome\n", .{word});
    } else {
        std.debug.print("{} is not a palindrome\n", .{word});
    }
}
